INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(29120, 5, 0, 'koKR', 'Niegdyś, dawno temu, byłem królem tego imperium. Za życia byłem jego obrońcą. Po śmierci wróciłem jako zdobywca. Teraz znów strzegę królestwa. Ironia losu, prawda?');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29852, 'koKR', '%s wspina się tunelem!', '', 0),
(32271, 'koKR', 'To królestwo należy do Plagi. Wstęp mają tylko umarli!', '', 0),
(32273, 'koKR', 'Głupotą było tu przychodzić.', '', 0),
(32274, 'koKR', 'Jak rozkaże Anub\'arak!', '', 0),
(32275, 'koKR', 'Jesteśmy oblężeni! Uderzyć i przynieść mi ich trupy!', '', 0),
(32276, 'koKR', 'Musimy utrzymać wrota. Do ataku! Rozerwijcie ich na strzępy!', '', 0),
(32277, 'koKR', 'Wrót trzeba bronić za wszelką cenę. Rozszarpcie ich!', '', 0),
(32278, 'koKR', 'Pilnujcie tego tunelu. Nie możemy nikogo przepuścić!', '', 0),
(32279, 'koKR', 'Słyszę kroki. Miejcie się na baczności.', '', 0),
(32280, 'koKR', 'Wyczuwam żywych. Przygotujcie się.', '', 0),
(32281, 'koKR', 'One są głodne....', '', 0),
(32282, 'koKR', 'Pora na obiad, moje pupilki!', '', 0),
(32283, 'koKR', 'Powinienem być wdzięczny... ale dawno utraciłem tę zdolność....', '', 0),
(32308, 'koKR', 'Czeka cię wieczna męka!', '', 0),
(32309, 'koKR', 'Na własnej skórze poznasz moją udrękę!', '', 0),
(32310, 'koKR', 'Taki był twój wybór.', '', 0),
(32311, 'koKR', 'Wkrótce wezwie cię głos pana.', '', 0),
(32312, 'koKR', 'Auum na-l ak-k-k-k, isshhh.', '', 0),
(32313, 'koKR', 'Przybądźcie, bracia! Ucztujcie na ich ciałach!', '', 0),
(32314, 'koKR', 'Twoja zbroja jest bezużyteczna wobec mojej szarańczy!', '', 0),
(32315, 'koKR', 'Uunak-hissss tik-k-k-k-k!', '', 0),
(32316, 'koKR', 'Niech spadnie na was zaraza!', '', 0),
(32317, 'koKR', 'Ahhh... RAAAAAGH! Nie sądziłem... że kiedyś się od niego uwolnię....', '', 0);
